section.script:
//
// Script to hide the first image in the body since it is already shown as Hero
(function() {
  var container = document.getElementById('post-content-container');
  if (container) {
    var firstImg = container.querySelector('img');
    if (firstImg) {
      // Check if it is wrapped in a standard Blogger separator div
      var parent = firstImg.closest('.separator');
      if (parent) {
        parent.style.display = 'none';
      } else {
        // If no separator, just hide the image
        firstImg.style.display = 'none';
      }
    }
  }
})();
//

body.script:
//
(function(){const toggle=document.getElementById('dark-mode-toggle');const root=document.documentElement;const savedTheme=localStorage.getItem('theme');const updateToggleUI=(isDark)=>{const btn=document.getElementById('dark-mode-toggle');if(!btn)return;if(isDark){btn.innerHTML='<svg class="i i-sun link-icon" viewBox="0 0 24 24"><circle cx="12" cy="12" r="5"></circle><path d="M12 1v2m0 18v2M4.2 4.2l1.4 1.4m12.8 12.8 1.4 1.4M1 12h2m18 0h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"></path></svg><span class="link-text">Modo Claro</span>'}else{btn.innerHTML='<svg class="i i-moon link-icon" viewbox="0 0 24 24"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg><span class="link-text">Modo Oscuro</span>'}};if(savedTheme==='dark'){root.classList.add('is-dark')}
updateToggleUI(root.classList.contains('is-dark'));window.toggleDarkMode=function(){root.classList.toggle('is-dark');const isDark=root.classList.contains('is-dark');localStorage.setItem('theme',isDark?'dark':'light');updateToggleUI(isDark)}
const yearSpan=document.getElementById('current-year');if(yearSpan){yearSpan.textContent=new Date().getFullYear()}
const cookieContainer=document.getElementById('cookie-notice-container');const acceptBtn=document.getElementById('accept-cookies');if(!localStorage.getItem('cookieConsent')&&cookieContainer){setTimeout(()=>{cookieContainer.classList.add('is-visible')},1000)}
if(acceptBtn){acceptBtn.addEventListener('click',function(){localStorage.setItem('cookieConsent','true');if(cookieContainer){cookieContainer.classList.remove('is-visible')}})}
const sidebarCloseBtn=document.getElementById('sidebar-close-btn');const sidebarCheckbox=document.getElementById('show-sidebar');if(sidebarCloseBtn&&sidebarCheckbox){sidebarCloseBtn.addEventListener('click',function(e){e.preventDefault();sidebarCheckbox.checked=!1})}
const searchCloseBtn=document.getElementById('close-search');const searchCheckbox=document.getElementById('show-search');if(searchCloseBtn&&searchCheckbox){searchCloseBtn.addEventListener('click',function(e){e.preventDefault();searchCheckbox.checked=!1})}
document.addEventListener('keydown',function(event){if(event.key==="Escape"&&searchCheckbox&&searchCheckbox.checked){searchCheckbox.checked=!1}})})()
