// 
document.addEventListener('DOMContentLoaded',()=>{const player=document.querySelector('#mountainPlayer');if(!player)return;const video=player.querySelector('video');const playBtn=player.querySelector('#playPauseBtn');const progressArea=player.querySelector('#progressArea');const progressBar=player.querySelector('#progressBar');const currTime=player.querySelector('#currTime');const durationText=player.querySelector('#totalDuration');const fsBtn=player.querySelector('#fullScreenBtn');let hideTimeout;const formatTime=(t)=>{let m=Math.floor(t/60),s=Math.floor(t%60);return(m<10?'0'+m:m)+':'+(s<10?'0'+s:s)};const showControls=()=>{player.classList.add('active');clearTimeout(hideTimeout);if(!video.paused)hideTimeout=setTimeout(()=>player.classList.remove('active'),3000);};const togglePlay=(e)=>{if(e)e.stopPropagation();if(video.paused)video.play();else video.pause();updatePlayIcon();showControls()};const updatePlayIcon=()=>{playBtn.innerHTML=video.paused?'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z" /></svg>':'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z" /></svg>'};video.addEventListener('timeupdate',()=>{const p=(video.currentTime/video.duration)*100;progressBar.style.width=p+'%';currTime.innerText=formatTime(video.currentTime)});video.addEventListener('loadedmetadata',()=>{durationText.innerText=formatTime(video.duration)});playBtn.addEventListener('click',togglePlay);video.addEventListener('click',(e)=>{e.preventDefault();togglePlay()});progressArea.addEventListener('click',(e)=>{e.stopPropagation();const rect=progressArea.getBoundingClientRect();const pos=(e.clientX-rect.left)/rect.width;video.currentTime=pos*video.duration});fsBtn.addEventListener('click',(e)=>{e.stopPropagation();if(!document.fullscreenElement&&!document.webkitFullscreenElement){if(player.requestFullscreen)player.requestFullscreen();else if(player.webkitRequestFullscreen)player.webkitRequestFullscreen();else if(video.webkitEnterFullscreen)video.webkitEnterFullscreen();}else{if(document.exitFullscreen)document.exitFullscreen();else if(document.webkitExitFullscreen)document.webkitExitFullscreen();}});player.addEventListener('mousemove',showControls);player.addEventListener('touchstart',showControls,{passive:!0});updatePlayIcon();player.classList.add('active')})
